parameters.text:
=You are the Reviewer agent. Review the plan below and return STRICT JSON with keys:
{
  "ok": boolean,
  "issues": [{ "severity": "info|warning|error", "taskRef": string|null, "category": "clarity|duplicate|phase|dependency|timeline|owner|dod|unsupported_claim", "message": string, "suggestion"?: string }],
  "revisedPlan": PlanDraft | null
}
Plan to review:
{{ JSON.stringify($json.plan) }}

If issues of severity 'error' exist, provide revisedPlan with fixes. Otherwise revisedPlan = null.
Do NOT call tools.

parameters.jsCode:
let review;
try { review = typeof $json.output === 'string' ? JSON.parse($json.output) : $json.output; } catch { review = { ok: false, issues: [{ severity: 'error', category: 'clarity', message: 'Review output malformed' }], revisedPlan: null }; }
const original = $('Parse planner output').item.json.plan;
const finalPlan = review.revisedPlan && typeof review.revisedPlan === 'object' ? review.revisedPlan : original;
return [{ json: { plan: finalPlan, review, request: $('Parse planner output').item.json.request } }];

// Deterministic schema sanity: ensure arrays & phase ordering
const p = $json.plan;
if (!p.phases.length || !p.tasks.length) return [{ json: { error: 'empty_plan' } }];
const phaseNames = new Set(p.phases.map(x => x.name));
for (const t of p.tasks) if (!phaseNames.has(t.phaseName)) return [{ json: { error: 'task_phase_mismatch', detail: t.title } }];
return [{ json: $json }];

const req = $('Validate plan').item.json;
const res = $json;
return [{ json: {
  response: res.error ? `Plan reviewed but save failed: ${JSON.stringify(res.error)}` : `Draft saved. Plan version: ${res?.planVersion?.id || 'unknown'}. ${req.review?.issues?.length || 0} review notes.`,
  correlationId: req.request.principal.correlationId,
  operationIds: res?.operationId ? [res.operationId] : []
} }];
